import Fastify, { type FastifyInstance, type FastifyServerOptions } from 'fastify';

import { registerErrorHandling } from './error-handler.js';
import { usersRoutes } from './routes/users.js';
import { profilesRoutes } from './routes/profiles.js';

export function buildApp(opts: FastifyServerOptions = {}): FastifyInstance {
  const app = Fastify({ logger: false, ...opts });

  // 1. 에러 핸들러 등록 (라우트보다 먼저)
  registerErrorHandling(app);

  // 2. 인증 데코레이터 (라우트 등록 전)
  app.decorateRequest('userId', null);

  // 태스크 14의 서버 기동 대기용. RealWorld 스펙 밖이므로 /api 프리픽스 없음.
  app.get('/health', async () => ({ status: 'ok' }));

  // 3. 라우트 플러그인 등록
  app.register(usersRoutes, { prefix: '/api' });
  app.register(profilesRoutes, { prefix: '/api' });

  return app;
}
export type ErrorBody = { errors: Record<string, string[]> };

/**
 * 계약(realworld-error-contract)이 정한 상태코드와 에러 바디를 함께 나르는 예외.
 * hurl이 메시지 문자열을 동등 비교하므로 팩토리 밖에서 문구를 만들지 않는다.
 */
export class ApiError extends Error {
  readonly status: number;
  readonly body: ErrorBody;

  constructor(status: number, errors: Record<string, string[]>) {
    super(`${status} ${JSON.stringify(errors)}`);
    this.name = 'ApiError';
    this.status = status;
    this.body = { errors };
  }

  /** 401 — 인증 헤더 누락, 서명 불일치, 만료 토큰 모두 동일하게 처리한다. */
  static tokenMissing(): ApiError {
    return new ApiError(401, { token: ['is missing'] });
  }

  /** 401 — 사용자 열거 방지를 위해 "없는 이메일"과 "비밀번호 불일치"를 구분하지 않는다. */
  static invalidCredentials(): ApiError {
    return new ApiError(401, { credentials: ['invalid'] });
  }

  static forbidden(resource: 'article' | 'comment'): ApiError {
    return new ApiError(403, { [resource]: ['forbidden'] });
  }

  static notFound(resource: 'article' | 'comment' | 'profile'): ApiError {
    return new ApiError(404, { [resource]: ['not found'] });
  }

  /** 409 — 공식 문서에는 없지만 errors_auth.hurl이 요구한다. */
  static conflict(field: 'username' | 'email'): ApiError {
    return new ApiError(409, { [field]: ['has already been taken'] });
  }

  static blank(...fields: string[]): ApiError {
    const errors: Record<string, string[]> = {};
    for (const field of fields) {
      errors[field] = ["can't be blank"];
    }
    return new ApiError(422, errors);
  }

  static unprocessable(errors: Record<string, string[]>): ApiError {
    return new ApiError(422, errors);
  }
}
import type { FastifyRequest, preHandlerHookHandler } from 'fastify';

import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { verifyToken } from './jwt.js';

declare module 'fastify' {
  interface FastifyRequest {
    userId: number | null;
  }
}

/**
 * RealWorld는 `Authorization: Token <jwt>` 스킴을 쓴다. `Bearer`는 인정하지
 * 않는다(스킴 이름만 대소문자 무시).
 */
function parseToken(req: FastifyRequest): string | null {
  const header = req.headers.authorization;
  if (typeof header !== 'string') return null;

  const [scheme, ...rest] = header.trim().split(/\s+/);
  if (scheme?.toLowerCase() !== 'token' || rest.length !== 1) return null;

  return rest[0] ?? null;
}

/** 토큰이 가리키는 사용자가 실제로 남아 있는지까지 확인한다(삭제된 사용자 방어). */
async function resolveUserId(req: FastifyRequest): Promise<number | null> {
  const token = parseToken(req);
  if (token === null) return null;

  const userId = verifyToken(token);
  if (userId === null) return null;

  const user = await prisma.user.findUnique({ where: { id: userId }, select: { id: true } });
  return user ? user.id : null;
}

/** 헤더 없음 / 스킴 불일치 / 토큰 무효 / 사용자 없음 → 전부 401. */
export const requireAuth: preHandlerHookHandler = async (req) => {
  const userId = await resolveUserId(req);
  if (userId === null) throw ApiError.tokenMissing();
  req.userId = userId;
};

/** 같은 실패 조건에서 401을 던지지 않고 익명(userId = null)으로 강등한다. */
export const optionalAuth: preHandlerHookHandler = async (req) => {
  req.userId = await resolveUserId(req);
};
import argon2 from 'argon2';

import { ApiError } from '../errors.js';

const MIN_LENGTH = 8;

/**
 * NIST SP 800-63B 기준: 최소 8자, 상한 없음(64자 이상 반드시 허용),
 * 문자 조합 규칙 없음.
 */
export function validatePasswordPolicy(password: unknown): void {
  if (typeof password !== 'string' || password === '') {
    throw ApiError.blank('password');
  }
  if (password.length < MIN_LENGTH) {
    throw ApiError.unprocessable({
      password: [`is too short (minimum is ${MIN_LENGTH} characters)`],
    });
  }
}

/** bcrypt의 72바이트 절단이 64자 이상 정책과 충돌하므로 argon2를 쓴다. */
export async function hashPassword(plain: string): Promise<string> {
  return argon2.hash(plain);
}

export async function verifyPassword(hash: string, plain: string): Promise<boolean> {
  try {
    return await argon2.verify(hash, plain);
  } catch {
    // 손상된 해시 문자열 등: 인증 실패로 취급한다.
    return false;
  }
}
import jwt from 'jsonwebtoken';

const EXPIRES_IN = '30d';

/**
 * 시크릿은 최초 사용 시점에 읽는다. server.ts가 `process.loadEnvFile()`를
 * 실행하기 전에 import 그래프가 먼저 평가되므로, 모듈 최상위에서 읽으면
 * .env의 JWT_SECRET을 놓친다.
 */
function secret(): string {
  const value = process.env.JWT_SECRET;
  if (!value) {
    throw new Error('JWT_SECRET 환경변수가 설정되지 않았습니다. .env를 확인하세요.');
  }
  return value;
}

export function signToken(userId: number): string {
  return jwt.sign({ sub: String(userId) }, secret(), {
    algorithm: 'HS256',
    expiresIn: EXPIRES_IN,
  });
}

/** 서명 실패·만료·형식 오류를 모두 null로 흡수한다(throw 금지). */
export function verifyToken(token: string): number | null {
  // secret()은 try 밖에서 부른다. 설정 누락(운영자 실수)까지 null로
  // 삼키면 모든 요청이 조용히 401이 된다.
  const key = secret();

  let payload: string | jwt.JwtPayload;
  try {
    payload = jwt.verify(token, key, { algorithms: ['HS256'] });
  } catch {
    return null;
  }

  if (typeof payload === 'string' || typeof payload.sub !== 'string') return null;

  const userId = Number(payload.sub);
  return Number.isInteger(userId) ? userId : null;
}
export type UserRecord = {
  email: string;
  username: string;
  bio: string | null;
  image: string | null;
};

export type UserDto = {
  email: string;
  token: string;
  username: string;
  bio: string | null;
  image: string | null;
};

export function toUserResponse(user: UserRecord, token: string): { user: UserDto } {
  return {
    user: {
      email: user.email,
      token,
      username: user.username,
      // undefined가 남으면 JSON에서 키가 사라져 `bio == null` 검증이 깨진다.
      bio: user.bio ?? null,
      image: user.image ?? null,
    },
  };
}
import { Prisma } from '@prisma/client';
import type { FastifyPluginAsync } from 'fastify';

import { hashPassword, validatePasswordPolicy, verifyPassword } from '../auth/password.js';
import { signToken } from '../auth/jwt.js';
import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { toUserResponse } from '../serializers/index.js';

/** 바디에서 `user.<field>`를 꺼낸다. 형식 검증은 호출자가 한다. */
function pick(body: unknown, field: string): unknown {
  if (typeof body !== 'object' || body === null) return undefined;
  const user = (body as Record<string, unknown>).user;
  if (typeof user !== 'object' || user === null) return undefined;
  return (user as Record<string, unknown>)[field];
}

/** 문자열이 아니거나 트림 후 빈 값인 필드를 모아 422로 던진다. */
function requireNonBlank(body: unknown, fields: string[]): string[] {
  const values: string[] = [];
  const blanks: string[] = [];

  for (const field of fields) {
    const value = pick(body, field);
    if (typeof value !== 'string' || value.trim() === '') {
      blanks.push(field);
      values.push('');
    } else {
      values.push(value);
    }
  }

  if (blanks.length > 0) throw ApiError.blank(...blanks);
  return values;
}

/** Prisma 유니크 제약 위반(P2002)을 409로 매핑한다. 경합으로 사전 검사를 통과한 경우. */
function conflictFrom(err: unknown): ApiError | null {
  if (!(err instanceof Prisma.PrismaClientKnownRequestError) || err.code !== 'P2002') return null;
  const target = err.meta?.target;
  const fields = Array.isArray(target) ? target.map(String) : [String(target ?? '')];
  return ApiError.conflict(fields.includes('email') ? 'email' : 'username');
}

export const usersRoutes: FastifyPluginAsync = async (app) => {
  // 가입. 성공 코드는 201이다 — 200이면 auth.hurl 첫 요청부터 전부 깨진다.
  app.post('/users', async (req, reply) => {
    const [username, email, password] = requireNonBlank(req.body, [
      'username',
      'email',
      'password',
    ]);
    validatePasswordPolicy(password);

    // username을 먼저 검사한다(계약이 정한 순서).
    if (await prisma.user.findUnique({ where: { username }, select: { id: true } })) {
      throw ApiError.conflict('username');
    }
    if (await prisma.user.findUnique({ where: { email }, select: { id: true } })) {
      throw ApiError.conflict('email');
    }

    const passwordHash = await hashPassword(password);
    let user;
    try {
      // bio/image는 저장하지 않는다. 컬럼 기본값 null이 그대로 응답에 나가야 한다.
      user = await prisma.user.create({ data: { username, email, passwordHash } });
    } catch (err) {
      throw conflictFrom(err) ?? err;
    }

    return reply.code(201).send(toUserResponse(user, signToken(user.id)));
  });

  app.post('/users/login', async (req) => {
    const [email, password] = requireNonBlank(req.body, ['email', 'password']);

    const user = await prisma.user.findUnique({ where: { email } });
    // 사용자 없음과 비밀번호 불일치를 구분하지 않는다(사용자 열거 방지).
    if (!user || !(await verifyPassword(user.passwordHash, password))) {
      throw ApiError.invalidCredentials();
    }

    return toUserResponse(user, signToken(user.id));
  });
};

